"""Supplier price sheet import."""


def parse_supplier_line(line):
    """Split one supplier CSV line into columns."""
    if line == "":
        return []
    return line.split(",")

verification_tests:
import pytest

from target import parse_supplier_line


def test_plain_line():
    assert parse_supplier_line("a,b,c") == ["a", "b", "c"]


def test_quoted_column_keeps_inner_comma():
    assert parse_supplier_line('a,"b,c",d') == ["a", "b,c", "d"]


def test_unterminated_quote_raises():
    with pytest.raises(ValueError):
        parse_supplier_line('a,"b,c')
